-- Curate water systems and ecology starter questions, completing all remaining catalog topics.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en, quiz_fil=v.quiz_fil, explanation_en=c.fact_en,
    explanation_fil=c.fact_fil, options=v.options::jsonb
FROM (VALUES
 ($$starter-water-cycle$$,$$A learner traces water evaporating from the ocean, forming clouds, and returning as rain. What connected process is being traced?$$,$$Sinusubaybayan ng mag-aaral ang pagsingaw ng tubig-dagat, pagbuo ng ulap, at pagbabalik bilang ulan. Anong magkakaugnay na proseso ito?$$,$$[{"en":"The water cycle","fil":"Siklo ng tubig","correct":true},{"en":"The rock cycle","fil":"Siklo ng bato","correct":false},{"en":"The nitrogen cycle","fil":"Siklo ng nitrogen","correct":false},{"en":"Ocean tides only","fil":"Pagtaas-baba lamang ng tubig-dagat","correct":false}]$$),
 ($$starter-water-evaporation$$,$$A puddle disappears faster on a warm, sunny day. Which change of state moves liquid water into the air?$$,$$Mas mabilis nawawala ang tubig sa kalsada sa mainit at maaraw na araw. Anong pagbabago ng estado ang naglilipat ng likidong tubig sa hangin?$$,$$[{"en":"Evaporation","fil":"Evaporation o pagsingaw","correct":true},{"en":"Condensation","fil":"Condensation","correct":false},{"en":"Freezing","fil":"Pagyeyelo","correct":false},{"en":"Deposition","fil":"Deposisyon","correct":false}]$$),
 ($$starter-water-condensation$$,$$Water vapor cools against the outside of a cold glass and forms droplets. What process formed them?$$,$$Lumamig ang singaw ng tubig sa labas ng malamig na baso at naging mga patak. Anong proseso ang bumuo sa mga ito?$$,$$[{"en":"Condensation","fil":"Condensation","correct":true},{"en":"Evaporation","fil":"Evaporation","correct":false},{"en":"Sublimation","fil":"Sublimation","correct":false},{"en":"Infiltration","fil":"Infiltration","correct":false}]$$),
 ($$starter-water-precipitation$$,$$Cloud droplets combine and fall to the ground as rain. What stage of the water cycle is this?$$,$$Nagsama-sama ang mga patak sa ulap at bumagsak bilang ulan. Anong yugto ng siklo ng tubig ito?$$,$$[{"en":"Precipitation","fil":"Precipitation o pag-ulan","correct":true},{"en":"Transpiration","fil":"Transpiration","correct":false},{"en":"Infiltration","fil":"Infiltration","correct":false},{"en":"Evaporation","fil":"Evaporation","correct":false}]$$),
 ($$starter-water-transpiration$$,$$Water leaves a plant’s leaves as vapor and enters the atmosphere. What process is occurring?$$,$$Lumilipat sa atmospera bilang singaw ang tubig mula sa mga dahon ng halaman. Anong proseso ito?$$,$$[{"en":"Transpiration","fil":"Transpiration","correct":true},{"en":"Condensation","fil":"Condensation","correct":false},{"en":"Runoff","fil":"Runoff","correct":false},{"en":"Deposition","fil":"Deposisyon","correct":false}]$$),
 ($$starter-water-sublimation$$,$$In a very cold, dry place, snow changes directly into water vapor without melting first. What is this change?$$,$$Sa napakalamig at tuyong lugar, nagiging singaw agad ang niyebe nang hindi muna natutunaw. Ano ang tawag sa pagbabagong ito?$$,$$[{"en":"Sublimation","fil":"Sublimation","correct":true},{"en":"Melting","fil":"Pagtunaw","correct":false},{"en":"Condensation","fil":"Condensation","correct":false},{"en":"Freezing","fil":"Pagyeyelo","correct":false}]$$),
 ($$starter-water-deposition$$,$$Water vapor changes directly into ice crystals on a cold surface, skipping the liquid stage. Which process is this?$$,$$Direktang nagiging kristal ng yelo ang singaw ng tubig sa malamig na ibabaw at nilalaktawan ang pagiging likido. Anong proseso ito?$$,$$[{"en":"Deposition","fil":"Deposisyon","correct":true},{"en":"Evaporation","fil":"Evaporation","correct":false},{"en":"Melting","fil":"Pagtunaw","correct":false},{"en":"Runoff","fil":"Runoff","correct":false}]$$),
 ($$starter-water-infiltration$$,$$After rain, water seeps downward through soil toward underground layers. What process is this?$$,$$Pagkatapos ng ulan, tumatagos pababa sa lupa ang tubig patungo sa mga patong sa ilalim nito. Anong proseso ito?$$,$$[{"en":"Infiltration","fil":"Infiltration o pagpasok sa lupa","correct":true},{"en":"Runoff","fil":"Runoff","correct":false},{"en":"Condensation","fil":"Condensation","correct":false},{"en":"Precipitation","fil":"Precipitation","correct":false}]$$),
 ($$starter-water-groundwater$$,$$A well draws water stored beneath Earth’s surface in spaces between soil and rock. What is this water called?$$,$$Kumukuha ng tubig ang balon mula sa nakaimbak sa mga puwang ng lupa at bato sa ilalim ng ibabaw. Ano ang tawag dito?$$,$$[{"en":"Groundwater","fil":"Tubig sa ilalim ng lupa","correct":true},{"en":"Runoff","fil":"Runoff","correct":false},{"en":"Cloud water","fil":"Tubig sa ulap","correct":false},{"en":"Ocean spray","fil":"Wisik ng karagatan","correct":false}]$$),
 ($$starter-water-aquifer$$,$$A permeable underground rock layer stores and transmits water to wells. What is the layer called?$$,$$Nag-iimbak at nagpapadaloy ng tubig sa mga balon ang permeable na patong ng bato sa ilalim ng lupa. Ano ang tawag dito?$$,$$[{"en":"An aquifer","fil":"Aquifer","correct":true},{"en":"A watershed","fil":"Watershed","correct":false},{"en":"A glacier","fil":"Glacier","correct":false},{"en":"A delta","fil":"Delta","correct":false}]$$),
 ($$starter-water-runoff$$,$$Rain flows over pavement into a storm drain instead of soaking into soil. What is this surface flow called?$$,$$Umaagos ang ulan sa sementadong daan papunta sa kanal sa halip na tumagos sa lupa. Ano ang tawag sa daloy na ito?$$,$$[{"en":"Surface runoff","fil":"Surface runoff","correct":true},{"en":"Infiltration","fil":"Infiltration","correct":false},{"en":"Transpiration","fil":"Transpiration","correct":false},{"en":"Condensation","fil":"Condensation","correct":false}]$$),
 ($$starter-water-gravity$$,$$Water in an elevated tank flows down a pipe toward a lower tap. Which force drives this downward movement?$$,$$Dumadaloy pababa sa tubo ang tubig mula sa mataas na tangke patungo sa gripo. Anong puwersa ang nagtutulak sa pagdaloy pababa?$$,$$[{"en":"Gravity","fil":"Grabidad","correct":true},{"en":"Magnetism","fil":"Magnetismo","correct":false},{"en":"Refraction","fil":"Refraction","correct":false},{"en":"Sound vibration","fil":"Panginginig ng tunog","correct":false}]$$),
 ($$starter-water-river-gravity$$,$$A river generally flows from mountain slopes toward lower land and the sea. What mainly drives its direction?$$,$$Karaniwang umaagos ang ilog mula sa bundok patungo sa mababang lupain at dagat. Ano ang pangunahing nagtutulak sa direksiyon nito?$$,$$[{"en":"Gravity pulling water downhill","fil":"Grabidad na humihila sa tubig pababa","correct":true},{"en":"The Moon pushing river water uphill","fil":"Pagtulak ng Buwan sa tubig paakyat","correct":false},{"en":"Evaporation pulling the whole river","fil":"Paghila ng evaporation sa buong ilog","correct":false},{"en":"Earth’s rotation stopping the flow","fil":"Paghinto ng agos dahil sa ikot ng Daigdig","correct":false}]$$),
 ($$starter-water-watershed$$,$$Rain falling on several hills drains into the same river system. What land area is being described?$$,$$Umaagos patungo sa iisang sistema ng ilog ang ulan mula sa ilang burol. Anong bahagi ng lupa ang inilalarawan?$$,$$[{"en":"A watershed or drainage basin","fil":"Watershed o basin ng daluyan ng tubig","correct":true},{"en":"An aquifer","fil":"Aquifer","correct":false},{"en":"A coastline","fil":"Baybayin","correct":false},{"en":"A tectonic plate","fil":"Tectonic plate","correct":false}]$$),
 ($$starter-water-reservoir$$,$$A city stores water behind a dam for later use. What is the stored body of water called?$$,$$Nag-iimbak ang lungsod ng tubig sa likod ng dam para magamit sa ibang pagkakataon. Ano ang tawag sa imbakan?$$,$$[{"en":"A reservoir","fil":"Reservoir","correct":true},{"en":"A watershed divide","fil":"Hati ng watershed","correct":false},{"en":"A water vapor cloud","fil":"Ulap ng singaw ng tubig","correct":false},{"en":"A fault","fil":"Fault","correct":false}]$$),
 ($$starter-water-snowmelt$$,$$Spring temperatures rise and mountain snow turns into flowing liquid water. What process is supplying streams?$$,$$Umiinit sa tagsibol at nagiging umaagos na likidong tubig ang niyebe sa bundok. Anong proseso ang nagdadagdag ng tubig sa sapa?$$,$$[{"en":"Snowmelt","fil":"Pagtunaw ng niyebe","correct":true},{"en":"Deposition","fil":"Deposisyon","correct":false},{"en":"Sublimation only","fil":"Sublimation lamang","correct":false},{"en":"Condensation","fil":"Condensation","correct":false}]$$),
 ($$starter-water-clouds$$,$$Warm moist air rises, cools, and forms tiny droplets that gather in the sky. How do clouds form?$$,$$Umaakyat at lumalamig ang mainit at mamasa-masang hangin kaya nabubuo ang maliliit na patak sa langit. Paano nabubuo ang ulap?$$,$$[{"en":"Water vapor condenses into droplets or ice crystals.","fil":"Nagiging mga patak o kristal ng yelo ang singaw ng tubig sa condensation.","correct":true},{"en":"Liquid water evaporates into visible drops immediately.","fil":"Agad nagiging nakikitang patak ang likidong tubig sa evaporation.","correct":false},{"en":"Wind turns dust into water.","fil":"Ginagawang tubig ng hangin ang alikabok.","correct":false},{"en":"Clouds are made only of smoke.","fil":"Usok lamang ang bumubuo sa ulap.","correct":false}]$$),
 ($$starter-water-states$$,$$Ice melts into water, then water boils into steam. Which states of matter are shown in order?$$,$$Natutunaw ang yelo at nagiging tubig, saka kumukulo at nagiging singaw. Anong mga estado ng matter ang ipinakikita ayon sa pagkakasunod?$$,$$[{"en":"Solid, liquid, gas","fil":"Solid, likido, gas","correct":true},{"en":"Gas, solid, liquid","fil":"Gas, solid, likido","correct":false},{"en":"Liquid, gas, solid","fil":"Likido, gas, solid","correct":false},{"en":"Solid, gas, liquid","fil":"Solid, gas, likido","correct":false}]$$),
 ($$starter-water-fresh$$,$$A student compares ocean water with water in a freshwater lake. Which statement about Earth’s water is accurate?$$,$$Inihahambing ng mag-aaral ang tubig-dagat at tubig-tabang sa lawa. Aling pahayag tungkol sa tubig ng Daigdig ang tama?$$,$$[{"en":"Only a small fraction of Earth’s water is readily available fresh water.","fil":"Maliit na bahagi lamang ng tubig ng Daigdig ang madaling makuhang tubig-tabang.","correct":true},{"en":"Most Earth water is fresh and stored in rivers.","fil":"Tubig-tabang ang karamihan ng tubig sa Daigdig at nasa ilog.","correct":false},{"en":"All groundwater is salty.","fil":"Maalat ang lahat ng tubig sa ilalim ng lupa.","correct":false},{"en":"Fresh water makes up every ocean.","fil":"Tubig-tabang ang bumubuo sa bawat karagatan.","correct":false}]$$),
 ($$starter-water-ocean-salt$$,$$A student evaporates seawater and finds crystals left behind. What explains the residue?$$,$$Pinasingaw ng mag-aaral ang tubig-dagat at may naiwang kristal. Ano ang paliwanag sa latak?$$,$$[{"en":"Dissolved salts remain when water evaporates.","fil":"Naiiwan ang mga natunaw na asin kapag sumingaw ang tubig.","correct":true},{"en":"Water creates salt while boiling.","fil":"Lumilikha ng asin ang tubig habang kumukulo.","correct":false},{"en":"The crystals are frozen oxygen.","fil":"Nagyelong oxygen ang mga kristal.","correct":false},{"en":"Evaporation turns sand into salt.","fil":"Ginagawang asin ng evaporation ang buhangin.","correct":false}]$$),
 ($$starter-water-sun-energy$$,$$Sunlight warms a lake and water begins to evaporate. What is the Sun’s role in the water cycle?$$,$$Pinaiinit ng sikat ng araw ang lawa at nagsisimulang sumingaw ang tubig. Ano ang papel ng Araw sa siklo ng tubig?$$,$$[{"en":"It supplies energy that drives evaporation.","fil":"Nagbibigay ito ng enerhiyang nagtutulak sa evaporation.","correct":true},{"en":"It pulls groundwater directly into clouds.","fil":"Direkta nitong hinihila sa ulap ang tubig sa ilalim ng lupa.","correct":false},{"en":"It causes precipitation to fall upward.","fil":"Nagiging sanhi ito upang umakyat ang ulan.","correct":false},{"en":"It turns saltwater into ice without cooling.","fil":"Ginagawang yelo nito ang maalat na tubig nang hindi pinapalamig.","correct":false}]$$),
 ($$starter-life-adaptation$$,$$A population of insects includes some individuals with coloring that helps them avoid predators. Over generations, what may happen?$$,$$May ilang insektong may kulay na tumutulong umiwas sa mandaragit. Ano ang maaaring mangyari sa maraming henerasyon?$$,$$[{"en":"That helpful inherited trait may become more common.","fil":"Maaaring dumami ang namamanang katangiang nakatutulong sa kanila.","correct":true},{"en":"Every insect changes color by choice in one day.","fil":"Kusang nagpapalit ng kulay ang lahat sa isang araw.","correct":false},{"en":"The trait disappears even if it helps survival.","fil":"Nawawala ang katangian kahit nakatutulong sa buhay.","correct":false},{"en":"Predators stop needing food.","fil":"Hindi na nangangailangan ng pagkain ang mga mandaragit.","correct":false}]$$),
 ($$starter-life-biodiversity$$,$$A forest contains many species of plants, animals, fungi, and microbes. What feature is high?$$,$$Maraming species ng halaman, hayop, fungi, at mikrobyo ang nasa gubat. Anong katangian ang mataas?$$,$$[{"en":"Biodiversity","fil":"Biodiversity o pagkakaiba-iba ng buhay","correct":true},{"en":"Air pressure","fil":"Presyon ng hangin","correct":false},{"en":"Salinity","fil":"Alat","correct":false},{"en":"One-species abundance only","fil":"Dami ng iisang species lamang","correct":false}]$$),
 ($$starter-life-carbon$$,$$Plants, animals, and other organisms contain carbon compounds. How does carbon commonly enter a food web?$$,$$May carbon compound ang mga halaman, hayop, at iba pang organismo. Paano karaniwang pumapasok ang carbon sa food web?$$,$$[{"en":"Plants take in carbon dioxide during photosynthesis.","fil":"Sumisipsip ng carbon dioxide ang mga halaman sa photosynthesis.","correct":true},{"en":"Animals create carbon from sunlight directly.","fil":"Direktang lumilikha ng carbon mula sa sikat ng araw ang hayop.","correct":false},{"en":"Carbon enters only through rocks.","fil":"Sa bato lamang pumapasok ang carbon.","correct":false},{"en":"Water removes all carbon from life.","fil":"Inaalis ng tubig ang lahat ng carbon sa buhay.","correct":false}]$$),
 ($$starter-life-carbon-sinks$$,$$A forest absorbs more carbon dioxide than it releases over time. What role is the forest playing?$$,$$Mas maraming carbon dioxide ang sinisipsip ng gubat kaysa inilalabas nito sa paglipas ng panahon. Ano ang papel nito?$$,$$[{"en":"A carbon sink","fil":"Carbon sink","correct":true},{"en":"A carbon source only","fil":"Pinagmumulan lamang ng carbon","correct":false},{"en":"A food-chain consumer","fil":"Consumer sa food chain","correct":false},{"en":"A water reservoir","fil":"Imbakan ng tubig","correct":false}]$$),
 ($$starter-life-consumers$$,$$A rabbit eats grass in a meadow. In a food chain, how is the rabbit classified?$$,$$Kumakain ng damo ang kuneho sa parang. Paano inuuri ang kuneho sa food chain?$$,$$[{"en":"A consumer","fil":"Consumer","correct":true},{"en":"A producer","fil":"Producer","correct":false},{"en":"A decomposer","fil":"Decomposer","correct":false},{"en":"A source of sunlight","fil":"Pinagmumulan ng sikat ng araw","correct":false}]$$),
 ($$starter-life-decay-carbon$$,$$A fallen leaf decomposes and carbon returns to soil and air. Which process contributes to this return?$$,$$Nabubulok ang nalaglag na dahon at bumabalik ang carbon sa lupa at hangin. Aling proseso ang tumutulong dito?$$,$$[{"en":"Decomposition and respiration by decomposers","fil":"Pagkabulok at respiration ng decomposer","correct":true},{"en":"Photosynthesis only","fil":"Photosynthesis lamang","correct":false},{"en":"Rock melting","fil":"Pagtunaw ng bato","correct":false},{"en":"Condensation","fil":"Condensation","correct":false}]$$),
 ($$starter-life-decomposers$$,$$Fungi break down a dead log and release nutrients back into the soil. What ecological role do fungi play?$$,$$Binubulok ng fungi ang patay na troso at ibinabalik ang sustansiya sa lupa. Ano ang papel ng fungi?$$,$$[{"en":"Decomposers","fil":"Decomposer","correct":true},{"en":"Producers","fil":"Producer","correct":false},{"en":"Primary consumers","fil":"Pangunahing consumer","correct":false},{"en":"Pollinators only","fil":"Pollinator lamang","correct":false}]$$),
 ($$starter-life-ecosystem$$,$$A pond study includes organisms, water, sunlight, and interactions among them. What is the whole interacting system?$$,$$Kabilang sa pag-aaral ng lawa ang mga organismo, tubig, sikat ng araw, at ugnayan nila. Ano ang buong sistemang ito?$$,$$[{"en":"An ecosystem","fil":"Ecosystem","correct":true},{"en":"A single population","fil":"Iisang populasyon","correct":false},{"en":"A cell","fil":"Selula","correct":false},{"en":"A weather front","fil":"Weather front","correct":false}]$$),
 ($$starter-life-food-chain$$,$$In grass → grasshopper → frog, what does the arrow show?$$,$$Sa damo → tipaklong → palaka, ano ang ipinakikita ng pana?$$,$$[{"en":"The direction energy moves from food to consumer.","fil":"Direksiyon ng paglipat ng enerhiya mula sa pagkain patungo sa consumer.","correct":true},{"en":"The direction animals migrate","fil":"Direksiyon ng paglipat ng hayop","correct":false},{"en":"Which organism is largest","fil":"Aling organismo ang pinakamalaki","correct":false},{"en":"That the organisms are the same species","fil":"Magkakapareho ng species ang mga organismo","correct":false}]$$),
 ($$starter-life-habitat$$,$$A mangrove forest provides food, shelter, and breeding places for crabs. What does the mangrove area provide?$$,$$Nagbibigay ng pagkain, kanlungan, at lugar-pangitlogan sa alimango ang bakawan. Ano ang ibinibigay ng bakawan?$$,$$[{"en":"A habitat","fil":"Habitat","correct":true},{"en":"A mineral","fil":"Mineral","correct":false},{"en":"A climate zone only","fil":"Climate zone lamang","correct":false},{"en":"A food molecule","fil":"Molekula ng pagkain","correct":false}]$$),
 ($$starter-life-photosynthesis$$,$$A plant receives light and takes in carbon dioxide and water to produce sugar. Which process is occurring?$$,$$Tumatanggap ng liwanag at kumukuha ng carbon dioxide at tubig ang halaman upang gumawa ng asukal. Anong proseso ito?$$,$$[{"en":"Photosynthesis","fil":"Photosynthesis","correct":true},{"en":"Cellular respiration only","fil":"Cellular respiration lamang","correct":false},{"en":"Decomposition","fil":"Pagkabulok","correct":false},{"en":"Fermentation in animals","fil":"Fermentation sa hayop","correct":false}]$$),
 ($$starter-life-phytoplankton$$,$$Tiny photosynthetic organisms drift near the ocean surface and support marine food webs. What are they?$$,$$Lumulutang malapit sa ibabaw ng dagat ang maliliit na organismong nagpo-photosynthesis at sumusuporta sa food web. Ano ang mga ito?$$,$$[{"en":"Phytoplankton","fil":"Phytoplankton","correct":true},{"en":"Zooplankton only","fil":"Zooplankton lamang","correct":false},{"en":"Coral rocks","fil":"Batong korales","correct":false},{"en":"Deep-sea mammals","fil":"Mammal sa malalim na dagat","correct":false}]$$),
 ($$starter-life-pollination$$,$$A bee carries pollen from one flower to another, enabling plant reproduction. What process is the bee helping?$$,$$Nagdadala ang bubuyog ng pollen mula sa isang bulaklak patungo sa iba upang makatulong sa pagpaparami ng halaman. Anong proseso ito?$$,$$[{"en":"Pollination","fil":"Pollination","correct":true},{"en":"Seed dispersal","fil":"Pagkalat ng buto","correct":false},{"en":"Germination","fil":"Pagsibol","correct":false},{"en":"Decomposition","fil":"Pagkabulok","correct":false}]$$),
 ($$starter-life-producers$$,$$In a food web, which organisms make organic food using sunlight or chemical energy?$$,$$Sa food web, aling mga organismo ang gumagawa ng organikong pagkain gamit ang sikat ng araw o enerhiyang kemikal?$$,$$[{"en":"Producers","fil":"Producer","correct":true},{"en":"Consumers","fil":"Consumer","correct":false},{"en":"Decomposers only","fil":"Decomposer lamang","correct":false},{"en":"Predators","fil":"Mandaragit","correct":false}]$$),
 ($$starter-life-respiration$$,$$A cell breaks down glucose to release usable energy for its activities. Which process is involved?$$,$$Binubuwag ng selula ang glucose upang maglabas ng magagamit na enerhiya. Anong proseso ang sangkot?$$,$$[{"en":"Cellular respiration","fil":"Cellular respiration","correct":true},{"en":"Photosynthesis","fil":"Photosynthesis","correct":false},{"en":"Pollination","fil":"Pollination","correct":false},{"en":"Transpiration","fil":"Transpiration","correct":false}]$$),
 ($$starter-life-seeds$$,$$A plant’s seeds travel away from the parent by wind, water, or animals. What process is occurring?$$,$$Naililipat palayo sa inang halaman ang mga buto sa tulong ng hangin, tubig, o hayop. Anong proseso ito?$$,$$[{"en":"Seed dispersal","fil":"Pagkalat ng mga buto","correct":true},{"en":"Pollination","fil":"Pollination","correct":false},{"en":"Fertilization only","fil":"Fertilization lamang","correct":false},{"en":"Cellular respiration","fil":"Cellular respiration","correct":false}]$$),
 ($$starter-earth-day-night$$,$$A classroom globe rotates under a lamp representing the Sun. Why does a location move from daylight into darkness?$$,$$Umiikot ang globo sa ilalim ng lampara na kumakatawan sa Araw. Bakit lumilipat mula liwanag tungo sa dilim ang isang lugar?$$,$$[{"en":"Earth’s rotation turns that location away from the Sun.","fil":"Inilalayo ng pag-ikot ng Daigdig ang lugar mula sa Araw.","correct":true},{"en":"Earth’s revolution around the Sun each day","fil":"Araw-araw na pag-ikot ng Daigdig sa Araw","correct":false},{"en":"The Moon covering the Sun every night","fil":"Pagtakip ng Buwan sa Araw gabi-gabi","correct":false},{"en":"The Sun switching off","fil":"Pagpatay ng Araw sa sarili nito","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,options)
WHERE c.content_key=v.content_key;
